#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# step15_teacher_distill_sandwich/scripts/70_install_trainer_shim.sh
#
#   Registers nnUNetTrainerSandwichDistill with nnunetv2 2.6.2.
#
#   WHY: 2.6.2 resolves `-tr <Name>` only by scanning the FILES inside
#   <site-packages>/nnunetv2/training/nnUNetTrainer.  The implementation stays
#   in trainer/ (single source of truth); the generated file only puts that
#   directory on sys.path and re-exports the classes, so training AND inference
#   (the predictor re-imports the trainer named in the checkpoint) both work.
#
#   Idempotent.  Delete the generated file to unregister.
#
#   usage: bash scripts/70_install_trainer_shim.sh
# ---------------------------------------------------------------------------
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
source scripts/env_step15.sh

SHIM_DIR="$("$STEP15_PYTHON" -c 'import os, nnunetv2; print(os.path.join(nnunetv2.__path__[0], "training", "nnUNetTrainer"))')"
TARGET="$SHIM_DIR/nnUNetTrainerStep15Distill.py"
TRAINER_DIR="$STEP15_ROOT/trainer"

echo "[shim] python        = $STEP15_PYTHON"
echo "[shim] target        = $TARGET"
echo "[shim] re-exports    = $TRAINER_DIR"

cat > "$TARGET" <<PYEOF
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
SHIM -- makes the step-15 teacher-distillation trainers discoverable.

GENERATED by step15_teacher_distill_sandwich/scripts/70_install_trainer_shim.sh
Do not edit here; edit that script so the shim stays reproducible.

The real implementation stays in:

    $TRAINER_DIR

This file carries no logic; it puts that directory on sys.path and re-exports
the classes.  Delete it to unregister.
"""
import sys

_TRAINER_DIR = ("$TRAINER_DIR")
if _TRAINER_DIR not in sys.path:
    sys.path.insert(0, _TRAINER_DIR)

from nnUNetTrainerSandwichDistill import nnUNetTrainerSandwichDistill  # noqa: E402,F401
from nnUNetTrainerSandwich import nnUNetTrainerSandwich                # noqa: E402,F401

__all__ = ["nnUNetTrainerSandwichDistill", "nnUNetTrainerSandwich"]
PYEOF

echo "[shim] verifying registration the way nnU-Net resolves it ..."
"$STEP15_PYTHON" - <<'PYEOF'
import os
import sys

import nnunetv2
from nnunetv2.utilities.find_class_by_name import recursive_find_python_class

folder = os.path.join(nnunetv2.__path__[0], "training", "nnUNetTrainer")
bad = []
for name in ("nnUNetTrainerSandwichDistill", "nnUNetTrainerSandwich"):
    cls = recursive_find_python_class(folder, name, "nnunetv2.training.nnUNetTrainer")
    print("[shim] %-28s -> %s" % (name, cls))
    if cls is None:
        bad.append(name)
if bad:
    sys.exit(1)
print("[shim] OK - trainers resolve")
PYEOF
